b:template.b:template-skin:

/* Variables */
:root {
  --cnn-red: #CC0000;
  --dark-text: #222222;
  --light-gray: #F1F1F1;
  --body-text: #333333;
  --link-color: #004B93;
}

/* Reset and base styles */
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  color: var(--body-text);
  line-height: 1.6;
}

/* Header styles */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: white;
  border-bottom: 1px solid #e5e5e5;
}

.header-content {
  max-width: 1280px;
  margin: 0 auto;
  padding: 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.site-title {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--cnn-red);
}

/* Navigation */
.nav-menu {
  display: none;
}

@media (min-width: 768px) {
  .nav-menu {
    display: flex;
    gap: 1.5rem;
  }
}

.nav-link {
  color: var(--dark-text);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
}

.nav-link:hover {
  color: var(--cnn-red);
}

/* Main content layout */
.main-content {
  max-width: 1280px;
  margin: 2rem auto;
  padding: 0 1rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 1024px) {
  .main-content {
    grid-template-columns: 2fr 1fr;
  }
}

/* Featured article */
.featured-article {
  position: relative;
  cursor: pointer;
}

.featured-image {
  width: 100%;
  aspect-ratio: 16/9;
  object-fit: cover;
}

.article-category {
  color: var(--cnn-red);
  font-weight: bold;
  text-transform: uppercase;
  font-size: 0.875rem;
  margin-top: 1rem;
}

.article-title {
  font-size: 1.5rem;
  font-weight: bold;
  margin: 0.5rem 0;
}

.article-snippet {
  color: var(--body-text);
  font-size: 0.875rem;
}

/* AdSense spaces */
.ad-space-header, .ad-space-sidebar, .ad-space-between-articles {
  background: var(--light-gray);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 1rem 0;
}

.ad-space-header {
  min-height: 90px;
}

.ad-space-sidebar {
  min-height: 600px;
}

.ad-space-between-articles {
  min-height: 250px;
  margin: 2rem 0;
}
